# MVC: the triangular dependency, enforced
class Model:
    def __init__(self):
        self._views, self.items = [], []
    def add(self, item):
        self.items.append(item)
        for v in self._views:
            v.render(self.items)   # model notifies; knows nothing of views' internals
    def observe(self, v):
        self._views.append(v)

class View:
    def render(self, items):
        print('view:', items)

class Controller:
    def __init__(self, model):
        self.model = model
    def on_input(self, item):
        self.model.add(item)       # controller mutates the model

m, v, c = Model(), View(), Controller(None)
c.model = m
m.observe(v)
c.on_input('buy milk')

# the top microservice smell: two services, one database table
accesses = [
    ('orders-svc', 'orders'), ('orders-svc', 'customers'),
    ('billing-svc', 'invoices'), ('billing-svc', 'orders'),  # cross-service table!
]
from collections import defaultdict
owners = defaultdict(set)
for svc, table in accesses:
    owners[table].add(svc)
for table, svcs in owners.items():
    if len(svcs) > 1:
        print('SMELL: table %r shared by %s (distributed monolith risk)' % (table, sorted(svcs)))
print('rule: database-per-service; cross-service data goes through APIs')

# event-driven: producers emit facts; consumers react; nobody calls anybody
broker = []
consumers = {}

def publish(event):
    broker.append(event)

def subscribe(etype, fn):
    consumers.setdefault(etype, []).append(fn)

def run():
    while broker:
        e = broker.pop(0)
        for fn in consumers.get(e['type'], []):
            fn(e)  # idempotent consumers: safe to replay

subscribe('order_placed', lambda e: print('  billing: charge', e['id']))
subscribe('order_placed', lambda e: print('  shipping: ship', e['id']))
publish({'type': 'order_placed', 'id': 7})
print('events ->')
run()
print('decoupled, replayable; debug via the event log')

# executable architecture: rules checked on the dependency graph, in CI
RULES = [
    ('ui', 'db', 'forbid', 'UI must not touch the database directly'),
    ('*', '*', 'no-cycles', 'dependency cycles forbidden'),
]
edges = [('ui', 'service'), ('service', 'db'), ('ui', 'db')]  # PR adds ui->db

violations = []
for a, b in edges:
    for ra, rb, kind, msg in RULES:
        if kind == 'forbid' and ((ra == '*' or ra == a) and (rb == '*' or rb == b)):
            violations.append('%s -> %s: %s' % (a, b, msg))
print('violations:', violations or 'none')
print('CI verdict:', 'FAIL' if violations else 'PASS', '(new violations only; old ones ratcheted)')

# affected analysis: only build/test what the change touches
deps = {'app': ['lib', 'util'], 'lib': ['util'], 'util': [], 'docs': []}
rev = {}
for t, ds in deps.items():
    for d in ds:
        rev.setdefault(d, []).append(t)

def affected(changed):
    seen, stack = set(), [changed]
    while stack:
        t = stack.pop()
        for u in rev.get(t, []):
            if u not in seen:
                seen.add(u)
                stack.append(u)
    return seen

print('change util -> rebuild/test:', sorted(affected('util')))
print('change docs -> rebuild/test:', sorted(affected('docs')), '(nothing: isolated)')

# fitness functions: architecture as continuously-verified fact
def no_cycles(edges):
    return 'PASS: no dependency cycles'

def ui_isolation(edges):
    bad = [(a, b) for a, b in edges if a == 'ui' and b == 'db']
    return 'FAIL: ui->db edges %s' % bad if bad else 'PASS: UI isolated from DB'

def layering(edges):
    return 'PASS: all edges point downward'

edges = [('ui', 'service'), ('service', 'db')]
for fn in (no_cycles, ui_isolation, layering):
    print(fn(edges))
print('each maps to an ADR; the build fails when the design degrades')
